def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    scarcity = 1.0 if slots <= 1 else 0.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    if danger >= 3:
        base = 112.0 if scarcity else 92.0
    elif danger >= 2:
        base = 96.0 if scarcity else 78.0
    elif danger >= 1:
        base = 76.0 if scarcity else 58.0
    else:
        base = 54.0 if scarcity else 36.0

    if highest_prev >= 160:
        target = 165.0 if danger >= 2 else 42.0
    elif highest_prev >= 140:
        target = highest_prev + 2.0 if danger >= 2 else 48.0
    elif highest_prev >= 110:
        target = highest_prev + 1.5 if scarcity or danger >= 1 else 52.0
    elif highest_prev > 0:
        target = max(base, avg_prev + 3.0)
    else:
        target = base

    target += rich_opp * 2.0
    target += urgent_opp * 1.5

    if day >= 8 and hp >= 7 and no_water_days == 0:
        target *= 0.9
    if day >= 9 and danger == 0:
        target *= 0.8

    reserve_floor = 0.0
    if hp > 3 and day < 9:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18

    bid = min(float(budget), float(target))
    if budget - bid < reserve_floor and danger < 2:
        bid = max(0.0, budget - reserve_floor)

    if danger >= 3:
        bid = min(float(budget), max(bid, 118.0 if scarcity else 98.0))
    elif danger >= 2:
        bid = min(float(budget), max(bid, 88.0 if scarcity else 72.0))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

