def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    base_bid = DAILY_SALARY * 0.70

    hp_bid_factor = 1.0
    if my_hp <= 2:
        hp_bid_factor = 1.2
    elif my_hp <= 4:
        hp_bid_factor = 1.05
    if my_no_water_days > 0:
        hp_bid_factor *= 1.15

    days_remaining = EPISODE_DAYS - current_day
    end_game_factor = 1.0
    if days_remaining <= 2:
        end_game_factor = 1.2
    elif days_remaining <= 4:
        end_game_factor = 1.1

    supply_bid_factor = 1.0
    if current_supply <= WATER_REQ + 2:
        supply_bid_factor = 1.15
    elif current_supply < 2 * WATER_REQ:
        supply_bid_factor = 1.05
    else:
        supply_bid_factor = 0.95

    highest_prev_bid = 0.0
    opponent_low_hp_count = 0
    opponent_low_budget_count = 0

    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                highest_prev_bid = max(highest_prev_bid, prev['bid'])

            if opp_data['hp'] <= 4:
                opponent_low_hp_count += 1
            if opp_data['budget'] < DAILY_SALARY * 2:
                opponent_low_budget_count += 1

    opponent_bid_adjustment = 0.0
    if highest_prev_bid > 0:
        if highest_prev_bid > DAILY_SALARY * 0.9:
            opponent_bid_adjustment = highest_prev_bid * 0.05
        elif highest_prev_bid > DAILY_SALARY * 0.7:
            opponent_bid_adjustment = highest_prev_bid * 0.02

        if num_alive_opponents > 0 and opponent_low_hp_count >= num_alive_opponents / 2:
            opponent_bid_adjustment += DAILY_SALARY * 0.1

        if num_alive_opponents > 0 and opponent_low_budget_count >= num_alive_opponents / 2:
            opponent_bid_adjustment -= DAILY_SALARY * 0.05
            opponent_bid_adjustment = max(0, opponent_bid_adjustment)

    calculated_bid = base_bid * hp_bid_factor * end_game_factor * supply_bid_factor + opponent_bid_adjustment

    calculated_bid = max(calculated_bid, DAILY_SALARY * 0.1)

    final_bid = min(my_budget, calculated_bid)

    final_bid = max(final_bid, 1.0)

    return final_bid

