        highest_prev = max(yesterday_bids)
    else:
        highest_prev = 0

    base_bid = DAILY_SALARY * 0.45
    if hp <= 3:
        base_bid = min(budget, DAILY_SALARY * 0.85)
    elif highest_prev > DAILY_SALARY * 0.7:
        base_bid = min(budget, DAILY_SALARY * 0.65)

