def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, conserve budget.
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.35))

    # Read yesterday bids as an immediate pressure signal.
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid depends on current supply: when supply is scarce, competition is higher.
    # supply is between 15 and 25.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # Lower ratio => scarcer => bid higher.
    scarcity_factor = 1.0 - max(0.0, min(1.0, supply_ratio))

    # Pressure escalation: if someone previously bid very high, they likely need water urgently.
    # We bid slightly below/near their pressure to avoid overpaying.
    urgent_threshold = DAILY_SALARY * 0.85

    # Also react to our own hp/no_water_days.
    hp = float(my_status['hp'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Conservative default: aim around 0.45-0.65 of salary depending on scarcity.
    base = DAILY_SALARY * (0.45 + 0.20 * scarcity_factor)

    if highest_prev_bid >= urgent_threshold:
        # High prior bids: increase, but not to full salary unless we are in danger.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.92
        elif hp <= 3:
            target = DAILY_SALARY * 0.78
        else:
            # Bid near but not above the observed pressure.
            target = min(DAILY_SALARY * 0.75, highest_prev_bid + 5.0)
    else:
        # If no extreme pressure yesterday, bid enough to secure without burning budget.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * (0.80 + 0.10 * scarcity_factor)
        elif hp <= 3:
            target = DAILY_SALARY * (0.65 + 0.10 * scarcity_factor)
        else:
            # Slightly undercut the likely average.
            target = base

    # Convert to feasible bid: can't exceed budget.
    bid = max(0.0, min(float(my_status['budget']), float(target)))

    # Final safeguard: if budget is very low, bid all-in.
    if my_status['budget'] <= DAILY_SALARY * 0.15:
        bid = float(my_status['budget'])

    return float(bid)
